package com.vizu.identidade.onboarding.service;
import com.vizu.identidade.integracao.service.OutboxService; import com.vizu.identidade.onboarding.dto.*; import com.vizu.identidade.onboarding.repository.OnboardingRepository; import java.util.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class OnboardingService { private static final UUID OWNER=UUID.fromString("00000000-0000-0000-0000-000000000003"); private final OnboardingRepository repo;private final PasswordEncoder passwords;private final OutboxService outbox; public OnboardingService(OnboardingRepository repo,PasswordEncoder passwords,OutboxService outbox){this.repo=repo;this.passwords=passwords;this.outbox=outbox;} @Transactional public OnboardingResponse create(OnboardingRequest r){UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),user=UUID.randomUUID();repo.tenant(tenant,r.nomeFantasia(),r.razaoSocial(),digits(r.cnpj()),r.telefone(),r.diaVencimento());repo.config(tenant,r.nomeFantasia(),r.subdominio().toLowerCase());repo.store(store,tenant,r.lojaNome(),r.telefone(),r.logradouro(),r.numero(),r.bairro(),r.cidade(),r.estado().toUpperCase(),digits(r.cep()),r.capacidadeSimultanea());repo.user(user,tenant,r.adminNome(),r.adminEmail().toLowerCase(),r.telefone(),passwords.encode(r.senha()));repo.links(user,store,tenant,OWNER);outbox.contratante(tenant,true,"America/Sao_Paulo");outbox.loja(store,tenant,r.lojaNome(),r.capacidadeSimultanea(),true);return new OnboardingResponse(tenant,store,user);} private static String digits(String v){return v.replaceAll("\\D","");} }
